// Terminology / glossary
// Facts reflect public information through mid-2026. Items marked "(verify current)"
// may have changed; check the latest before citing them in an interview.
export const TERM_CATS = [
  { id: 'bank', name: 'Banking' },
  { id: 'cap', name: 'Capital & Regulation' },
  { id: 'ins', name: 'Insurance' },
  { id: 'am', name: 'Asset & Wealth Mgmt' },
  { id: 'pay', name: 'Payments & Fintech' },
  { id: 'mkt', name: 'Rates & Markets' },
  { id: 'acct', name: 'Accounting & Valuation' },
  { id: 'ma', name: 'M&A & LBO' },
];

export const TERMS = [
  // ───────────────────────────── Banking ─────────────────────────────
  { id: 'nii', term: 'NII', full: 'Net Interest Income', cat: 'bank',
    def: `Interest income on loans, securities, and cash minus interest expense on deposits and borrowings. The largest revenue line for most commercial banks — often ~60–80% of revenue for regionals, less for universal banks with big fee businesses.`,
    why: `NII guidance is usually the headline number investors react to on bank earnings calls.` },
  { id: 'nim', term: 'NIM', full: 'Net Interest Margin', cat: 'bank',
    def: `Net interest income ÷ average interest-earning assets (loans, securities, cash, fed funds sold), annualized and usually on a fully taxable-equivalent basis. Driven by asset yields, funding costs, balance-sheet mix, and the rate environment; U.S. banks typically run ~2.5–3.5%.`,
    why: `The most-watched bank profitability metric — be ready to name its drivers and explain how a Fed cut moves it for an asset-sensitive bank.` },
  { id: 'net-interest-spread', term: 'Net interest spread', cat: 'bank',
    def: `Yield on interest-earning assets minus the cost of interest-bearing liabilities. Unlike NIM, it ignores "free" funding (non-interest-bearing deposits and equity), so NIM normally exceeds the spread — and the gap widens when rates are high.`,
    why: `A classic "what's the difference between NIM and spread?" question.` },
  { id: 'cost-of-funds', term: 'Cost of funds', cat: 'bank',
    def: `Interest expense ÷ average funding — either interest-bearing liabilities only, or total funding including non-interest-bearing deposits (the all-in cost). Rises with deposit betas, a shift toward CDs, and reliance on wholesale borrowings.`,
    why: `Cheap, stable funding is the core of a bank's franchise value and a key M&A attraction.` },
  { id: 'deposit-beta', term: 'Deposit beta', cat: 'bank',
    def: `The share of a change in benchmark rates (usually fed funds) passed through to deposit costs: Δ deposit cost ÷ Δ fed funds. A 40% beta means a 100bp hike raises deposit costs ~40bp. Cumulative betas in the 2022–23 hiking cycle ran well above the 2015–18 cycle.`,
    why: `Lower betas mean stickier, cheaper deposits; in cutting cycles, how fast "down betas" catch up drives NIM.` },
  { id: 'nib-deposits', term: 'NIB deposits', full: 'Non-interest-bearing (demand) deposits', cat: 'bank',
    def: `Checking balances on which the bank pays no interest — mostly business operating accounts and consumer checking. The cheapest, most valuable funding; their share of deposits fell in 2022–23 as clients moved cash into interest-bearing products.`,
    why: `A high NIB mix is a hallmark of a premium deposit franchise — exactly what acquirers pay up for.` },
  { id: 'core-deposits', term: 'Core deposits', cat: 'bank',
    def: `Stable, relationship-based deposits — checking, savings, money market, and smaller CDs — generally excluding brokered deposits and large (jumbo) CDs. They reprice slowly and are less likely to run, making them the heart of a bank's franchise value.`,
    why: `The base for the core deposit premium and the core deposit intangible (CDI) in bank M&A.` },
  { id: 'time-deposits', term: 'Time deposits (CDs)', cat: 'bank',
    def: `Deposits with a fixed term and rate (certificates of deposit) and early-withdrawal penalties. Costlier than transaction accounts and reprice only at maturity, so a rising CD mix lifts funding costs with a lag — and lets them fall with a lag after rate cuts.` },
  { id: 'brokered-deposits', term: 'Brokered deposits', cat: 'bank',
    def: `Deposits placed through a third-party deposit broker, such as brokered CDs and certain sweep programs. Rate-sensitive and less sticky than core deposits; only well-capitalized banks can accept them without restriction, and heavy reliance draws regulatory scrutiny.` },
  { id: 'uninsured-deposits', term: 'Uninsured deposits', cat: 'bank',
    def: `Deposit balances above the FDIC limit of $250,000 per depositor, per insured bank, per ownership category. Concentrated uninsured deposits make a bank vulnerable to fast runs, as SVB showed in March 2023.`,
    why: `Since 2023, investors check uninsured deposits as a % of total and how much is covered by cash plus available borrowing capacity.` },
  { id: 'fhlb-advances', term: 'FHLB advances', full: 'Federal Home Loan Bank advances', cat: 'bank',
    def: `Secured loans from the 11 Federal Home Loan Banks — government-sponsored cooperatives — to member banks, thrifts, credit unions, and insurers, collateralized by mortgages and securities. A key wholesale funding source and liquidity backstop, heavily tapped during the March 2023 turmoil.` },
  { id: 'discount-window', term: 'Discount window', cat: 'bank',
    def: `The Federal Reserve's standing lending facility for depository institutions, secured by pledged collateral (with haircuts) at the primary credit rate. Since 2023, regulators push banks to pre-position collateral and test access, because stigma historically discouraged its use.` },
  { id: 'btfp', term: 'BTFP', full: 'Bank Term Funding Program', cat: 'bank',
    def: `Emergency Fed facility launched in March 2023 after SVB failed, offering loans of up to one year against Treasuries and agency securities valued at par rather than market value. It stopped making new loans on March 11, 2024.`,
    why: `Shows how unrealized securities losses became a liquidity problem — and how policymakers responded.` },
  { id: 'efficiency-ratio', term: 'Efficiency ratio', cat: 'bank',
    def: `Non-interest expense ÷ total revenue (NII, often FTE, plus non-interest income). Lower is better — roughly ≤55% is strong and ≥65% weak. "Positive operating leverage" (revenue growing faster than expenses) pushes it down.`,
    why: `The quickest read on cost discipline and the starting point for merger cost-save math.` },
  { id: 'ppnr', term: 'PPNR', full: 'Pre-Provision Net Revenue', cat: 'bank',
    def: `NII + non-interest income − non-interest expense: earnings before credit costs and taxes. Measures a bank's capacity to absorb credit losses out of ongoing earnings.`,
    why: `Central to stress tests and to comparing banks through the credit cycle.` },
  { id: 'provision', term: 'Provision for credit losses', cat: 'bank',
    def: `The income-statement expense that adjusts the allowance for credit losses to management's expected-loss estimate: provision = net charge-offs + reserve build (or − reserve release). A non-cash charge.`,
    why: `Provisions, not charge-offs, hit earnings; under CECL, reserve builds front-run downturns and releases flatter earnings in recoveries.` },
  { id: 'acl', term: 'ACL', full: 'Allowance for Credit Losses', cat: 'bank',
    def: `Contra-asset reserve for expected lifetime credit losses on loans (and certain other assets) under CECL. Ending ACL = beginning ACL + provision − net charge-offs. Quoted as a % of loans (reserve ratio) or of nonperforming loans (coverage ratio).` },
  { id: 'cecl', term: 'CECL', full: 'Current Expected Credit Loss', cat: 'bank',
    def: `The U.S. GAAP credit-loss model (ASC 326) requiring lifetime expected losses to be reserved when a loan is originated or acquired, using reasonable and supportable forecasts. Replaced the incurred-loss model — effective 2020 for most large SEC filers and 2023 for other banks.`,
    why: `Front-loads provisions, makes reserves swing with economic forecasts, and creates the day-2 "double count" in bank M&A.` },
  { id: 'nco', term: 'NCOs', full: 'Net Charge-Offs', cat: 'bank',
    def: `Loans written off as uncollectible minus recoveries on loans previously charged off. NCOs reduce the allowance rather than hitting earnings directly. NCO ratio = annualized NCOs ÷ average loans.`,
    why: `The realized-loss measure — compare it with provision to see whether a bank is building or releasing reserves.` },
  { id: 'npa', term: 'NPLs / NPAs', full: 'Nonperforming loans / assets', cat: 'bank',
    def: `NPLs are loans on nonaccrual status — interest no longer recognized because full collection is doubtful, typically at 90+ days past due. NPAs add other real estate owned (OREO, i.e., foreclosed property) and other repossessed assets. Quoted as a % of loans (plus OREO).` },
  { id: 'criticized-classified', term: 'Criticized & classified loans', cat: 'bank',
    def: `Regulatory risk ratings for weaker credits. Criticized loans include "special mention" plus all classified loans; classified loans are rated substandard, doubtful, or loss. Rising criticized balances are an early warning ahead of nonaccruals and charge-offs.` },
  { id: 'ci-loans', term: 'C&I loans', full: 'Commercial & industrial loans', cat: 'bank',
    def: `Loans to businesses for working capital, equipment, and acquisitions — usually floating-rate (SOFR-based) and secured by business assets. Typically a 100% risk weight; large floating-rate C&I books make a bank asset-sensitive.` },
  { id: 'cre', term: 'CRE', full: 'Commercial real estate loans', cat: 'bank',
    def: `Loans secured by income-producing property (office, retail, industrial, multifamily, hotels) or for construction and land development. Interagency guidance flags a concentration when CRE is ≥300% of total risk-based capital with ≥50% growth over 36 months, or construction is ≥100%.`,
    why: `Office and rent-regulated multifamily exposure was the key credit worry for regional banks in 2023–25.` },
  { id: 'ldr', term: 'Loan-to-deposit ratio', full: 'LDR', cat: 'bank',
    def: `Total loans ÷ total deposits. High ratios (roughly 90–100%+) signal reliance on wholesale funding and tighter liquidity; low ratios mean excess deposits parked in lower-yielding securities and cash.` },
  { id: 'afs', term: 'AFS securities', full: 'Available-for-sale', cat: 'bank',
    def: `Debt securities carried at fair value, with unrealized gains and losses recorded in AOCI (equity) instead of net income; credit losses run through an allowance. Can be sold for liquidity or repositioning.`,
    why: `Category I–II banks' CET1 includes AFS marks via AOCI; most other banks have opted out (verify current proposals).` },
  { id: 'htm', term: 'HTM securities', full: 'Held-to-maturity', cat: 'bank',
    def: `Debt securities a bank has the intent and ability to hold to maturity, carried at amortized cost — unrealized gains or losses don't hit earnings, AOCI, or regulatory capital and are only disclosed. Selling HTM securities can "taint" the whole portfolio.`,
    why: `SVB's large HTM losses were invisible in reported capital but very real economically.` },
  { id: 'aoci', term: 'AOCI', full: 'Accumulated other comprehensive income', cat: 'bank',
    def: `An equity account holding unrealized gains and losses that bypass net income — mainly AFS securities, cash-flow hedges, pension items, and FX translation. Rising rates create AOCI losses that cut book and tangible book value; they reverse as bonds pull to par.`,
    why: `"TBV ex-AOCI" and AOCI accretion as securities mature are recurring themes in bank earnings and M&A.` },
  { id: 'asset-sensitive', term: 'Asset-sensitive vs liability-sensitive', cat: 'bank',
    def: `An asset-sensitive bank's assets reprice faster than its liabilities (floating-rate loans, lots of cash, sticky deposits), so NII rises when rates rise and falls when they're cut. A liability-sensitive bank (e.g., a thrift with fixed-rate mortgages) shows the opposite. Banks reposition with swaps and securities.`,
    why: `Establish this first before answering "what happens to this bank if the Fed cuts?"` },
  { id: 'eve', term: 'EVE', full: 'Economic value of equity', cat: 'bank',
    def: `Present value of a bank's assets minus present value of its liabilities and off-balance-sheet positions. EVE sensitivity shows how that value moves under rate shocks, complementing 12–24-month NII sensitivity; results depend heavily on the assumed duration of deposits.` },
  { id: 'fixed-asset-repricing', term: 'Fixed-rate asset repricing', cat: 'bank',
    def: `The NII tailwind as low-yielding fixed-rate securities and loans — many put on in 2020–21 — mature or pay down and are reinvested at higher current yields. A major NII driver for many banks since 2024, even as the Fed cut short-term rates.` },
  { id: 'fee-income', term: 'Non-interest income', full: 'Fee income', cat: 'bank',
    def: `Revenue other than NII: deposit service charges, card and interchange fees, wealth/trust and asset management fees, treasury management, mortgage banking, capital markets and investment banking, and trading. Generally valued more highly than NII because it's capital-light and less rate-sensitive.` },
  { id: 'treasury-management', term: 'Treasury management', full: 'TM / cash management', cat: 'bank',
    def: `Services that help corporate clients move and manage cash — payments, collections, liquidity, and account services — earning fees and gathering sticky operating deposits. Citi's version, Treasury and Trade Solutions, anchors its Services business.`,
    why: `TM relationships supply low-cost commercial deposits and open doors for corporate and investment banking.` },
  { id: 'correspondent-banking', term: 'Correspondent banking', cat: 'bank',
    def: `Services one bank provides to another — often a smaller or foreign bank — such as clearing, payments, FX, settlement, and account services. Global banks earn fees and deposits acting as correspondents.`,
    why: `These financial-institution client relationships give FIG coverage bankers a natural entry point with bank clients.` },
  { id: 'tbv', term: 'TBV / TBVPS', full: 'Tangible book value (per share)', cat: 'bank',
    def: `Common equity minus goodwill and other intangibles (often net of related deferred tax liabilities), excluding preferred stock; TBVPS = TBV ÷ shares outstanding. Approximates the loss-absorbing equity regulators recognize.`,
    why: `The denominator of P/TBV — the core bank valuation multiple — and the focus of M&A dilution analysis.` },
  { id: 'tce-ratio', term: 'TCE ratio', full: 'Tangible common equity ratio', cat: 'bank',
    def: `Tangible common equity ÷ tangible assets (total assets − goodwill − intangibles). A simple, non-risk-weighted leverage measure that includes AOCI, so it fell sharply for many banks when rates rose in 2022.`,
    why: `A cross-check on regulatory ratios because it isn't affected by risk weights or the AOCI filter.` },
  { id: 'roa', term: 'ROA', full: 'Return on assets', cat: 'bank',
    def: `Net income ÷ average total assets. Around 1% is solid for a U.S. bank and ~1.3%+ is top-tier. ROE ≈ ROA × leverage (assets ÷ equity), so a 1.2% ROA at 10x leverage ≈ 12% ROE.` },
  { id: 'rotce', term: 'ROTCE', full: 'Return on tangible common equity', cat: 'bank',
    def: `Net income to common (usually adding back after-tax intangible amortization) ÷ average tangible common equity. Removes acquisition goodwill so acquisitive and organically grown banks compare cleanly.`,
    why: `Drives P/TBV — justified P/TBV = (ROTCE − g) ÷ (cost of equity − g) — and it's the return metric bank CEOs set public targets on.` },
  { id: 'cash-sorting', term: 'Cash sorting', cat: 'bank',
    def: `Clients moving low-yielding balances (checking, savings, brokerage sweep cash) into higher-yielding money market funds, CDs, or Treasuries as rates rise. It shrinks cheap deposits and pushes up funding costs for banks and brokers.`,
    why: `A defining 2022–23 theme, especially for Schwab and other brokers that earn a spread on sweep cash.` },

  // ─────────────────────── Capital & Regulation ───────────────────────
  { id: 'cet1', term: 'CET1', full: 'Common Equity Tier 1', cat: 'cap',
    def: `The highest-quality regulatory capital: common stock, surplus, and retained earnings (plus AOCI for Category I–II banks), less goodwill and intangibles (net of DTLs) and other deductions such as certain DTAs. CET1 ratio = CET1 ÷ RWA, with a 4.5% minimum plus buffers.`,
    why: `The binding constraint on most banks' loan growth, buybacks, and M&A capacity.` },
  { id: 'at1', term: 'AT1', full: 'Additional Tier 1 capital', cat: 'cap',
    def: `Perpetual, deeply subordinated capital whose coupons can be cancelled without triggering default. In the U.S. it's mainly non-cumulative perpetual preferred stock; in Europe and the UK, contingent convertible bonds (CoCos). Tier 1 = CET1 + AT1, with a 6% minimum Tier 1 ratio before buffers.` },
  { id: 'tier2', term: 'Tier 2 capital', cat: 'cap',
    def: `Gone-concern capital: qualifying subordinated debt (at least five years' original maturity, amortizing for capital purposes over its final five years) plus the allowance for credit losses up to 1.25% of risk-weighted assets. Total capital = Tier 1 + Tier 2, with an 8% minimum before buffers.` },
  { id: 'rwa', term: 'RWA', full: 'Risk-weighted assets', cat: 'cap',
    def: `Exposures weighted by riskiness to size capital needs. U.S. standardized weights include 0% for cash and Treasuries, 20% for Fannie/Freddie MBS, 50% for qualifying first-lien mortgages, 100% for most commercial and consumer loans, and 150% for high-volatility CRE. The largest banks also compute model-based RWA and must meet the stricter result (Collins floor).` },
  { id: 'scb', term: 'SCB', full: 'Stress capital buffer', cat: 'cap',
    def: `The Fed's firm-specific CET1 buffer for banks with ≥$100B in assets (since 2020): projected peak-to-trough CET1 decline in the severely adverse stress scenario plus four quarters of planned common dividends, floored at 2.5%. It replaced the fixed 2.5% capital conservation buffer in the standardized approach; dipping into buffers triggers automatic limits on dividends, buybacks, and bonuses.`,
    why: `Sets each large bank's required CET1 — and therefore how much excess capital it can return.` },
  { id: 'gsib-surcharge', term: 'G-SIB surcharge', cat: 'cap',
    def: `An extra CET1 buffer for global systemically important banks, scored on size, interconnectedness, complexity, cross-jurisdictional activity, and — under the U.S. "method 2" — reliance on short-term wholesale funding. U.S. surcharges range roughly from 1.0% to 4.5% (verify current).`,
    why: `Citi, BofA, and Wells Fargo are among the eight U.S. G-SIBs, and Barclays is on the FSB's global G-SIB list — know how the surcharge feeds their CET1 targets.` },
  { id: 'leverage-ratio', term: 'Tier 1 leverage ratio', cat: 'cap',
    def: `Tier 1 capital ÷ average total on-balance-sheet assets — a non-risk-based backstop with a 4% minimum (5% for a bank to be "well-capitalized"). Tends to bind for banks holding lots of low-risk-weight assets such as cash and Treasuries.` },
  { id: 'slr', term: 'SLR / eSLR', full: 'Supplementary leverage ratio', cat: 'cap',
    def: `Tier 1 capital ÷ total leverage exposure (on-balance-sheet assets plus derivatives, repo, and off-balance-sheet commitments) for Category I–III banks, with a 3% minimum. G-SIBs face an enhanced buffer — historically 5% at the holding company and 6% at bank subsidiaries — which regulators moved to recalibrate in 2025 (verify current).`,
    why: `The eSLR can constrain low-risk balance-sheet activity such as Treasury market-making and repo.` },
  { id: 'lcr', term: 'LCR', full: 'Liquidity coverage ratio', cat: 'cap',
    def: `High-quality liquid assets ÷ projected net cash outflows over a 30-day stress period; at least 100% for the largest banks, with reduced or no requirements for some Category III–IV banks.`,
    why: `Post-SVB, investors also look past the LCR at uninsured-deposit coverage and discount-window readiness.` },
  { id: 'hqla', term: 'HQLA', full: 'High-quality liquid assets', cat: 'cap',
    def: `Assets convertible to cash quickly with little loss under stress: Level 1 (cash, Fed reserves, Treasuries, Ginnie Mae MBS) with no haircut; Level 2A (e.g., Fannie/Freddie MBS) with a 15% haircut; Level 2B (certain corporate bonds and equities) with a 50% haircut, with caps on Level 2 assets.` },
  { id: 'nsfr', term: 'NSFR', full: 'Net stable funding ratio', cat: 'cap',
    def: `Available stable funding ÷ required stable funding over a one-year horizon, at least 100%. Rewards equity, long-term debt, and stable retail deposits, and penalizes funding long-term assets with short-term wholesale money. The U.S. rule took effect in July 2021.` },
  { id: 'tlac', term: 'TLAC', full: 'Total loss-absorbing capacity', cat: 'cap',
    def: `G-SIBs must hold enough equity plus eligible long-term debt to be recapitalized through bail-in — losses on creditors, not taxpayers — in resolution. U.S. G-SIB holdcos need external TLAC of at least 18% of RWA and 7.5% of leverage exposure, plus buffers. A 2023 proposal would extend long-term debt rules to banks ≥$100B (verify current).` },
  { id: 'mrel', term: 'MREL', full: 'Minimum requirement for own funds and eligible liabilities', cat: 'cap',
    def: `The EU and UK counterpart to TLAC: resolution authorities set bank-specific minimums for capital plus bail-in-able debt. Drives steady issuance of holding-company senior and senior non-preferred debt by European banks.`,
    why: `Relevant to Barclays, which issues MREL-eligible debt from its holding company, Barclays PLC.` },
  { id: 'cocos', term: 'CoCos', full: 'Contingent convertible bonds', cat: 'cap',
    def: `Hybrid bonds that convert into equity or are written down when a trigger is hit — such as CET1 falling below 5.125% or 7% — or when the regulator deems the bank non-viable. Most European AT1 is issued in this form.`,
    why: `The March 2023 write-down of about CHF 16B of Credit Suisse AT1s, while shareholders still received UBS stock, upended the expected creditor hierarchy.` },
  { id: 'basel-endgame', term: 'Basel III endgame', full: 'Basel 3.1', cat: 'cap',
    def: `The final Basel III reforms: revised standardized credit-risk weights, a new operational-risk approach, FRTB market risk, CVA changes, and a 72.5% output floor. The July 2023 U.S. proposal implied a ~16% aggregate CET1 increase for affected holdcos; regulators later signaled a more capital-neutral re-proposal. The UK targets 2027 (verify both).`,
    why: `Lighter capital rules mean more excess capital for buybacks and M&A — a key 2025–26 bank theme.` },
  { id: 'output-floor', term: 'Output floor', cat: 'cap',
    def: `A Basel III endgame rule: risk-weighted assets calculated with a bank's internal models can't fall below 72.5% of RWA under the standardized approaches. Limits the capital benefit of modeling; phased in over several years in most jurisdictions.`,
    why: `Especially consequential for European banks, which rely more heavily on internal models than U.S. banks.` },
  { id: 'ccar-dfast', term: 'CCAR / DFAST', full: 'Fed stress tests', cat: 'cap',
    def: `The Fed's supervisory stress tests for banks with ≥$100B in assets (annual for most, every other year for Category IV), projecting losses, revenue, and capital under a severely adverse scenario. Results set each bank's stress capital buffer. In 2025 the Fed moved to average results over two years and publish its models for comment (verify current).` },
  { id: 'tailoring', term: 'Tailoring categories', cat: 'cap',
    def: `The 2019 U.S. framework scaling prudential rules by size and risk: Category I (U.S. G-SIBs); II (≥$700B in assets or ≥$75B cross-jurisdictional activity); III (≥$250B, or ≥$75B in nonbank assets, short-term wholesale funding, or off-balance-sheet exposure); IV ($100–250B).`,
    why: `Explains why banks plan carefully before crossing $100B or $250B — and why some deals are sized to "jump" a threshold.` },
  { id: 'pca', term: 'Well-capitalized (PCA)', full: 'Prompt Corrective Action', cat: 'cap',
    def: `Statutory framework requiring escalating supervisory action as a bank's capital falls. To be "well-capitalized," an insured bank needs CET1 ≥ 6.5%, Tier 1 ≥ 8%, total capital ≥ 10%, and leverage ≥ 5%. Status affects brokered deposits, deposit insurance pricing, and expansion activities.` },
  { id: 'dodd-frank', term: 'Dodd-Frank Act', cat: 'cap',
    def: `The 2010 U.S. post-crisis law that created enhanced prudential standards and stress tests for large banks, the CFPB, the FSOC, the Volcker Rule, orderly liquidation authority, and the Durbin debit-interchange cap. The 2018 EGRRCPA raised the main enhanced-standards threshold from $50B to $100B in assets.` },
  { id: 'volcker', term: 'Volcker Rule', cat: 'cap',
    def: `Dodd-Frank provision generally barring banking entities from proprietary trading and limiting their investments in hedge funds and private equity funds ("covered funds"), with exemptions for market-making, underwriting, and hedging. Simplified by amendments in 2019–20.` },
  { id: 'durbin', term: 'Durbin Amendment', cat: 'cap',
    def: `Dodd-Frank provision, implemented through the Fed's Regulation II, capping debit-card interchange for issuers with ≥$10B in assets at 21¢ + 0.05% of the transaction + a 1¢ fraud-prevention adjustment. The Fed proposed lowering the cap in 2023 (verify current).`,
    why: `Crossing $10B in assets costs a bank much of its debit interchange — a classic consideration in community bank M&A.` },
  { id: 'cra', term: 'CRA', full: 'Community Reinvestment Act', cat: 'cap',
    def: `A 1977 law requiring banks to help meet the credit needs of their entire communities, including low- and moderate-income neighborhoods. CRA ratings are weighed in merger applications. A 2023 rule modernizing CRA was enjoined, and regulators moved in 2025 to rescind it (verify current).` },
  { id: 'us-regulators', term: 'U.S. bank regulators', full: 'Fed / OCC / FDIC / CFPB', cat: 'cap',
    def: `The Federal Reserve supervises bank and financial holding companies and state member banks; the OCC charters and supervises national banks; the FDIC insures deposits, supervises state non-member banks, and resolves failed banks; the CFPB supervises consumer compliance at banks over $10B (its activity was sharply scaled back in 2025 — verify current). States charter state banks.`,
    why: `Knowing who approves what matters for deal timelines — e.g., the OCC for a national bank merger and the Fed for the holding company.` },
  { id: 'deposit-insurance', term: 'Deposit insurance', full: 'FDIC / Deposit Insurance Fund', cat: 'cap',
    def: `The FDIC insures deposits up to $250,000 per depositor, per insured bank, per ownership category, backed by the Deposit Insurance Fund that banks pay premiums into. In March 2023 a systemic risk exception let the FDIC protect all SVB and Signature depositors, with the cost recovered through a special assessment on larger banks.` },
  { id: 'ring-fencing', term: 'Ring-fencing (UK)', cat: 'cap',
    def: `UK rule in force since 2019 requiring large banks to separate core retail and small-business deposit-taking into a ring-fenced bank insulated from investment banking. Barclays runs Barclays Bank UK PLC (ring-fenced) alongside Barclays Bank PLC (non-ring-fenced, including the investment bank). The government has moved to loosen the regime (verify current).` },
  { id: 'srt', term: 'SRT', full: 'Significant (synthetic) risk transfer', cat: 'cap',
    def: `A bank keeps a loan portfolio but buys credit protection on a junior or mezzanine slice — often via credit-linked notes sold to private credit funds, hedge funds, or insurers — reducing RWA and capital needs. Long common in Europe and growing in the U.S. since the Fed clarified the treatment in 2023.`,
    why: `A key link between banks and private credit, and a capital-optimization tool.` },
  { id: 'bhc', term: 'BHC', full: 'Bank holding company', cat: 'cap',
    def: `A company that controls a bank, supervised by the Fed under the Bank Holding Company Act. The holdco issues most public equity and debt, must be a "source of strength" for its bank, and funds its payouts with upstream bank dividends. Electing financial holding company status permits securities, insurance, and merchant banking.` },
  { id: 'consent-order', term: 'Consent order / asset cap', cat: 'cap',
    def: `A formal enforcement agreement in which a bank commits to fix deficiencies (risk management, controls, compliance) under regulatory oversight. Severe actions can limit growth — e.g., the Fed's asset cap on Wells Fargo, imposed in 2018 at about $1.95T and lifted in June 2025.`,
    why: `Remediation progress is central to both the Citi and Wells Fargo investment stories.` },

  // ───────────────────────────── Insurance ─────────────────────────────
  { id: 'gwp-nwp', term: 'GWP / NWP', full: 'Gross / net written premiums', cat: 'ins',
    def: `Gross written premiums are total premiums on policies written in a period before reinsurance; net written premiums are after premiums ceded to reinsurers. Retention ratio = NWP ÷ GWP.`,
    why: `Written premium growth — split into rate and exposure — is the P&C top-line growth measure.` },
  { id: 'written-vs-earned', term: 'Written vs earned premium', cat: 'ins',
    def: `Written premium is booked when a policy is sold; earned premium is recognized as revenue pro rata as coverage is provided. The unearned portion sits in the unearned premium reserve (UPR), a liability that unwinds into revenue over the policy term. Net earned premium (NEP) is the denominator of the combined ratio.` },
  { id: 'loss-ratio', term: 'Loss ratio', cat: 'ins',
    def: `Losses plus loss adjustment expenses (LAE — the cost of investigating, defending, and settling claims) ÷ net earned premiums. Usually broken into current accident year ex-catastrophes, catastrophe losses, and prior-year reserve development.` },
  { id: 'expense-ratio', term: 'Expense ratio', cat: 'ins',
    def: `Underwriting expenses — commissions, other acquisition costs, and underwriting overhead — ÷ premiums: net earned premiums on a GAAP basis, net written premiums on a statutory basis.` },
  { id: 'combined-ratio', term: 'Combined ratio', cat: 'ins',
    def: `Loss ratio + expense ratio (+ policyholder dividend ratio). Below 100% means an underwriting profit — underwriting income = NEP × (1 − combined ratio); above 100% is an underwriting loss that long-tail insurers may still offset with investment income. Operating ratio = combined ratio − investment income ratio.`,
    why: `The core P&C metric; analysts focus on the "underlying" accident-year combined ratio excluding cats and prior-year development.` },
  { id: 'pyd', term: 'PYD', full: 'Prior-year reserve development', cat: 'ins',
    def: `Changes in the estimated cost of claims from earlier accident years. Favorable development (reserve releases) adds to current earnings; adverse development (reserve strengthening) reduces them. Calendar-year results include PYD; accident-year results exclude it to show current underwriting.`,
    why: `Persistent adverse development — e.g., from social inflation in casualty lines — erodes trust in book value and P/BV multiples.` },
  { id: 'ibnr', term: 'IBNR', full: 'Incurred but not reported', cat: 'ins',
    def: `Actuarial reserves for losses that have occurred but haven't yet been reported, plus expected development on known claims. Together with case reserves (set by adjusters on reported claims) they form loss and LAE reserves — usually a P&C insurer's largest liability, especially in long-tail lines.` },
  { id: 'float', term: 'Float', cat: 'ins',
    def: `Money an insurer holds between collecting premiums and paying claims — mainly loss reserves plus unearned premiums, net of premiums receivable and prepaid acquisition costs — invested for the insurer's benefit. With a combined ratio below 100%, float costs less than nothing.`,
    why: `Berkshire Hathaway's model; long-tail lines generate more float per premium dollar.` },
  { id: 'net-investment-income', term: 'Net investment income (insurers)', cat: 'ins',
    def: `Interest, dividends, and other income on an insurer's invested assets — mostly investment-grade bonds — net of investment expenses and excluding realized and unrealized gains. Rises as the portfolio reinvests at higher yields, a significant earnings tailwind for insurers since 2022.` },
  { id: 'short-long-tail', term: 'Short-tail vs long-tail lines', cat: 'ins',
    def: `Short-tail lines (property, auto physical damage) report and settle claims quickly but carry catastrophe volatility. Long-tail lines (general liability, workers' comp, medical malpractice, D&O) settle over many years — generating more float and investment income, but more reserve uncertainty.` },
  { id: 'cat-losses', term: 'Cat losses / PML', full: 'Catastrophe losses / probable maximum loss', cat: 'ins',
    def: `Losses from natural or man-made catastrophes (hurricanes, wildfires, earthquakes, severe convective storms) above a reporting threshold. Probable maximum loss estimates the loss from an event of a given return period (e.g., 1-in-100 or 1-in-250 years) and guides how much reinsurance to buy.` },
  { id: 'reinsurance', term: 'Reinsurance', cat: 'ins',
    def: `Insurance bought by insurers. The insurer "cedes" part of its premiums and losses and the reinsurer "assumes" them (and may buy its own protection, called retrocession). Provides capacity, capital relief, and earnings stability. Treaty reinsurance covers a whole book automatically; facultative covers individual risks one by one.` },
  { id: 'quota-share', term: 'Quota share', cat: 'ins',
    def: `Proportional reinsurance: the reinsurer takes a fixed percentage of the premiums and losses on a book of business and pays the insurer a ceding commission to cover acquisition costs and overhead. Provides capital relief and supports growth.` },
  { id: 'xol', term: 'Excess of loss (XOL)', cat: 'ins',
    def: `Non-proportional reinsurance that pays losses above a retention up to a limit — per risk, per occurrence, or for catastrophes (cat XOL). Protects against severe losses rather than sharing every loss.`,
    why: `"Quota share vs excess of loss" is a standard insurance interview question.` },
  { id: 'ils', term: 'Cat bonds / ILS', full: 'Insurance-linked securities', cat: 'ins',
    def: `Securities that transfer insurance risk — mostly natural catastrophe — to capital-markets investors; principal is lost if a defined trigger event occurs, and proceeds sit in collateral trusts. Together with collateralized reinsurance and sidecars, this "alternative capital" totals roughly $100B+ (verify current).` },
  { id: 'social-inflation', term: 'Social inflation', cat: 'ins',
    def: `Liability claim costs rising faster than general inflation, driven by larger jury awards ("nuclear verdicts"), third-party litigation funding, attorney advertising, and broader liability theories. A major cause of adverse reserve development in U.S. casualty lines since the late 2010s.` },
  { id: 'hard-soft-market', term: 'Hard vs soft market', cat: 'ins',
    def: `A hard market brings rising rates, tighter terms, and scarce capacity, typically after heavy losses or capital depletion; a soft market brings falling rates and looser terms as capital is plentiful. After a multi-year hard market, property pricing softened in 2025 while casualty stayed firm (verify current).` },
  { id: 'es-lines', term: 'E&S lines', full: 'Excess & surplus lines', cat: 'ins',
    def: `Coverage for hard-to-place or unusual risks that standard (admitted) carriers decline, written by non-admitted insurers with freedom of rate and form. One of the fastest-growing segments of U.S. P&C in recent years.` },
  { id: 'mga', term: 'MGA', full: 'Managing general agent', cat: 'ins',
    def: `A specialist intermediary with delegated authority from insurers to underwrite, price, and bind policies (and sometimes handle claims) in niche lines, earning commissions without bearing underwriting risk. A hot area for private equity and specialty insurance M&A.` },
  { id: 'broker-vs-carrier', term: 'Insurance broker vs carrier', cat: 'ins',
    def: `Carriers take underwriting risk and hold capital and reserves; brokers (e.g., Marsh McLennan, Aon, WTW, Arthur J. Gallagher, Brown & Brown) advise and place coverage for clients, earning commissions and fees without balance-sheet risk. Brokers are valued on EV/EBITDA and P/E, driven by organic revenue growth and margins; carriers on P/BV and P/E.`,
    why: `Brokers are serial acquirers and PE favorites — roll-up M&A is a big source of FIG deal flow.` },
  { id: 'ebitdac', term: 'EBITDAC', cat: 'ins',
    def: `EBITDA adjusted for the change in estimated acquisition earnout payables — a broker metric (used by Arthur J. Gallagher, among others) that strips out noise from re-measuring earnouts on acquisitions.` },
  { id: 'sap', term: 'SAP', full: 'Statutory accounting principles', cat: 'ins',
    def: `The NAIC's conservative, solvency-focused accounting for U.S. insurers: acquisition costs are expensed immediately, "non-admitted" assets are excluded, and most bonds are carried at amortized cost. Statutory surplus is the capital measure regulators use, and it limits the dividends subsidiaries can pay up to the holding company.` },
  { id: 'rbc', term: 'RBC ratio', full: 'Risk-based capital ratio', cat: 'ins',
    def: `NAIC measure: an insurer's total adjusted capital ÷ its authorized control level RBC. Regulatory intervention starts below 200% (the company action level); insurers hold well above that — life insurers commonly target ~350–450%+ — to support ratings.`,
    why: `Determines how much capital an insurer can upstream for dividends, buybacks, and M&A.` },
  { id: 'bv-ex-aoci', term: 'BVPS ex-AOCI', cat: 'ins',
    def: `Book value per share excluding accumulated other comprehensive income (mainly unrealized gains and losses on the bond portfolio). Used because rate-driven bond price swings don't reflect underwriting performance for a buy-and-hold investor.`,
    why: `Insurer P/BV multiples are usually quoted on book value ex-AOCI.` },
  { id: 'annuities', term: 'Annuities (fixed, FIA, VA, RILA)', cat: 'ins',
    def: `Contracts that accumulate savings and/or provide guaranteed income. Fixed annuities credit a declared rate; fixed indexed annuities (FIAs) credit index-linked returns with a 0% floor; variable annuities invest in separate-account funds; registered index-linked annuities (RILAs) offer index-linked returns with a buffer or floor on losses. U.S. sales hit records in 2023–24 as rates rose.` },
  { id: 'spread-income', term: 'Spread income (life & annuities)', cat: 'ins',
    def: `The difference between the yield an insurer earns on assets backing spread products (fixed annuities, funding agreements, universal life) and the crediting rate it pays policyholders. Managing that spread through asset allocation and asset-liability matching is the core economics of annuity writers.` },
  { id: 'mortality-longevity', term: 'Mortality, longevity & morbidity risk', cat: 'ins',
    def: `Mortality risk: policyholders die sooner than priced (life insurance). Longevity risk: annuitants and pensioners live longer than priced. Morbidity risk: illness or disability exceeds expectations (health, disability, long-term care). Long-term care has been a notorious source of reserve charges.` },
  { id: 'dac', term: 'DAC', full: 'Deferred acquisition costs', cat: 'ins',
    def: `Successful policy acquisition costs (mainly commissions) capitalized under GAAP and amortized over the life of the policies; under statutory accounting they are expensed immediately — one reason fast-growing insurers show weaker statutory results.` },
  { id: 'ldti', term: 'LDTI', full: 'Long-Duration Targeted Improvements', cat: 'ins',
    def: `ASU 2018-12, effective 2023 for large SEC filers. Insurers update cash-flow assumptions for traditional long-duration contracts at least annually, discount liabilities at an upper-medium-grade (single-A) bond rate updated quarterly through OCI, carry market risk benefits (e.g., variable annuity guarantees) at fair value, and amortize DAC on a simplified constant-level basis.` },
  { id: 'prt', term: 'PRT', full: 'Pension risk transfer', cat: 'ins',
    def: `Transactions in which corporate pension sponsors transfer pension obligations to insurers — through buyouts (the insurer takes over the liabilities) or buy-ins (the insurer reimburses the plan). A large, growing annuity market in the U.S. and especially the UK.` },
  { id: 'solvency-ii', term: 'Solvency II', cat: 'ins',
    def: `The EU's risk-based insurance capital regime (since 2016), built on market-consistent valuation; insurers report solvency capital requirement (SCR) coverage ratios, commonly ~150–250%. The UK now operates its own version, Solvency UK.` },
  { id: 'pe-backed-insurers', term: 'PE-backed insurers', cat: 'ins',
    def: `Alternative asset managers own or partner with life and annuity insurers — e.g., Apollo–Athene, KKR–Global Atlantic, Brookfield–American Equity — gathering long-duration liabilities and investing them in higher-yielding private credit. Often paired with asset-intensive reinsurance of annuity blocks to affiliated Bermuda reinsurers, which regulators scrutinize.`,
    why: `The convergence of asset management and insurance is one of the biggest FIG themes; it gives the manager perpetual capital.` },

  // ─────────────────────── Asset & Wealth Mgmt ───────────────────────
  { id: 'aum', term: 'AUM', full: 'Assets under management', cat: 'am',
    def: `The market value of assets a firm manages for clients. Ending AUM = beginning AUM + net flows + market performance (± FX and acquisitions). For traditional managers, revenue ≈ average AUM × fee rate, so earnings move with markets.` },
  { id: 'fpaum', term: 'FPAUM', full: 'Fee-paying AUM', cat: 'am',
    def: `The part of AUM that actually earns management fees — charged on committed capital during many private equity funds' investment periods, and on invested capital or NAV elsewhere. Excludes capital not yet earning fees and GP commitments.`,
    why: `Drives an alternative manager's management-fee revenue more directly than headline AUM.` },
  { id: 'auca', term: 'AUC/A', full: 'Assets under custody and/or administration', cat: 'am',
    def: `Assets a custodian holds or services — safekeeping, settlement, fund accounting, administration — for institutional clients, earning small basis-point fees. Trust banks such as BNY and State Street service tens of trillions of dollars.` },
  { id: 'net-flows', term: 'Net flows / organic growth', cat: 'am',
    def: `Net flows = client inflows minus outflows (redemptions). Organic growth rate = net flows ÷ beginning AUM, often annualized — growth excluding market moves and acquisitions.`,
    why: `The metric most correlated with asset manager valuation multiples.` },
  { id: 'fee-rate', term: 'Fee rate (bps)', cat: 'am',
    def: `Management fee revenue ÷ average AUM, in basis points. Ranges from low single-digit bps for passive index products to roughly 1–2% for private-markets funds, with active mutual funds in between. The mix shift to passive has driven sustained industry fee compression.` },
  { id: 'performance-fee', term: 'Performance / incentive fee', cat: 'am',
    def: `A fee tied to investment results — e.g., a share of returns above a benchmark or high-water mark in hedge funds, or periodic incentive fees in BDCs and other evergreen vehicles. Paid more often than carried interest but still volatile.` },
  { id: 'carried-interest', term: 'Carried interest (carry)', cat: 'am',
    def: `The general partner's share of a closed-end fund's profits — typically 20% — paid after limited partners get their capital back plus a preferred return, usually with a GP catch-up. Realized only on exits, so it is lumpy and valued at much lower multiples than fee earnings.` },
  { id: 'hurdle', term: 'Hurdle rate / preferred return', cat: 'am',
    def: `The minimum annual return — commonly 8% — LPs must earn before the GP receives carried interest. A catch-up provision then gives the GP a disproportionate share of profits until it has received its full carry percentage.` },
  { id: 'waterfall', term: 'Distribution waterfall', cat: 'am',
    def: `The order in which fund proceeds are split. A European (whole-fund) waterfall pays carry only after LPs recover all contributed capital plus the hurdle; an American (deal-by-deal) waterfall can pay carry on individual exits earlier, typically with a clawback if later deals underperform.` },
  { id: 'fre', term: 'FRE', full: 'Fee-related earnings', cat: 'am',
    def: `Management fees plus fee-related performance revenues and other recurring fees, minus the compensation and operating costs that support them; excludes carried interest and investment gains. Stable and recurring, so the market capitalizes FRE at far higher multiples than carry.`,
    why: `The headline metric for alternative managers such as Blackstone, Apollo, KKR, Ares, and Blue Owl.` },
  { id: 'de', term: 'DE', full: 'Distributable earnings', cat: 'am',
    def: `FRE plus realized net performance revenues (carry and incentive fees) and realized investment income, minus interest and taxes — the cash earnings that fund dividends. More volatile than FRE because realizations depend on exit markets.` },
  { id: 'dry-powder', term: 'Dry powder', cat: 'am',
    def: `Committed but uncalled capital in private funds. High dry powder signals future deployment — and, for funds that charge fees on invested capital, future management-fee growth (often disclosed as "AUM not yet paying fees").` },
  { id: 'perpetual-capital', term: 'Perpetual capital', cat: 'am',
    def: `Capital with an indefinite term that doesn't need to be returned and re-raised — e.g., insurance general accounts managed under long-term agreements, listed vehicles, BDCs, non-traded REITs, and other evergreen funds. Durable fee streams earn premium valuation multiples.` },
  { id: 'gp-lp', term: 'GP / LP', full: 'General partner / limited partner', cat: 'am',
    def: `In a private fund, the general partner manages the fund, makes investment decisions, commits a small slice of capital, and earns fees and carry. Limited partners — pensions, endowments, sovereign wealth funds, insurers, and individuals — provide most of the capital with limited liability.` },
  { id: 'evergreen', term: 'Evergreen / semi-liquid funds', cat: 'am',
    def: `Open-ended private-markets vehicles — non-traded REITs and BDCs, interval and tender-offer funds — that raise capital continuously and offer limited periodic liquidity (e.g., up to ~5% of NAV per quarter). The main channel for selling alternatives to wealthy individuals.`,
    why: `Redemption limits get tested in stress, as with BREIT's withdrawal caps starting in late 2022.` },
  { id: 'retail-alts', term: 'Retail alts / 401(k) access', cat: 'am',
    def: `Alternative managers' push to distribute private-markets products to individual investors through wealth platforms and, increasingly, defined-contribution retirement plans. An August 2025 executive order directed regulators to ease the inclusion of alternatives in 401(k) plans (verify current rulemaking).`,
    why: `The private wealth channel is the biggest growth vector alternative managers cite.` },
  { id: 'active-passive', term: 'Active vs passive', cat: 'am',
    def: `Active managers try to beat a benchmark through security selection; passive funds (index mutual funds and ETFs) track an index at very low cost. Passive overtook active in U.S. fund assets around the start of 2024, pushing active managers toward active ETFs, alternatives, and consolidation.` },
  { id: 'ria', term: 'RIA', full: 'Registered investment adviser', cat: 'am',
    def: `A firm registered with the SEC or the states that gives investment advice for a fee (often ~1% of AUM) under a fiduciary duty. Independent RIAs have been taking share from wirehouses and are being rolled up by PE-backed aggregators.` },
  { id: 'wirehouse', term: 'Wirehouse', cat: 'am',
    def: `A large national full-service brokerage with an employed adviser force — in the U.S., Morgan Stanley, Merrill (Bank of America), Wells Fargo Advisors, and UBS. Advisers increasingly "break away" to independent and RIA models.`,
    why: `Merrill and Wells Fargo Advisors are major pieces of the BofA and Wells Fargo franchises.` },
  { id: 'comp-ratio', term: 'Comp ratio', cat: 'am',
    def: `Compensation and benefits ÷ net revenue — the largest expense line for asset managers and investment banks and the main lever on margins. Advisory boutiques typically run higher comp ratios than diversified banks and asset managers.` },
  { id: 'private-credit', term: 'Private credit / direct lending', cat: 'am',
    def: `Loans made directly by non-bank lenders — private funds, BDCs, insurers — typically floating-rate senior secured loans to sponsor-backed middle-market companies, held rather than syndicated. A roughly $1.5–2T+ market that grew as banks retrenched (verify current).`,
    why: `Banks both compete and partner with private credit — e.g., Citi with Apollo and Wells Fargo with Centerbridge.` },
  { id: 'abf', term: 'ABF', full: 'Asset-based finance', cat: 'am',
    def: `Private lending backed by pools of financial or hard assets — consumer and mortgage loans, equipment, receivables, royalties — rather than one company's cash flows. Seen as the next leg of private credit growth, often sourced through forward-flow agreements with banks and fintech lenders.` },
  { id: 'secondaries', term: 'Secondaries / continuation vehicles', cat: 'am',
    def: `Purchases of existing private fund interests from LPs (LP-led) or of portfolio companies that a GP moves into a new vehicle (GP-led continuation funds). They provide liquidity when IPO and M&A exits are scarce, as in 2022–24.` },
  { id: 'bdc', term: 'BDC', full: 'Business development company', cat: 'am',
    def: `A closed-end investment company, taxed as a RIC, that lends mainly to U.S. middle-market companies. Must distribute at least 90% of taxable income and may borrow up to 2:1 debt-to-equity (150% asset coverage, allowed since 2018). Valued on price/NAV and dividend yield; most are externally managed by alternative managers.` },
  { id: 'clo', term: 'CLO', full: 'Collateralized loan obligation', cat: 'am',
    def: `A securitization of leveraged loans funded by tranches from AAA down to equity, with a manager actively trading the loan pool within set constraints. CLOs are the largest buyers of leveraged loans, and CLO management is a meaningful fee business for credit managers.` },

  // ─────────────────────── Payments & Fintech ───────────────────────
  { id: 'tpv', term: 'TPV', full: 'Total payment volume', cat: 'pay',
    def: `The dollar value of transactions processed over a period (companies also use GPV, GMV, or purchase volume). Payments revenue ≈ volume × take rate, so TPV growth is the top-line driver.` },
  { id: 'take-rate', term: 'Take rate', cat: 'pay',
    def: `Net revenue as a percentage of payment volume or GMV. Reflects pricing power, mix (cross-border, card-not-present, small merchants), and value-added services; compression is a recurring concern for acquirers and marketplaces.` },
  { id: 'interchange', term: 'Interchange', cat: 'pay',
    def: `The fee the merchant's acquirer pays the cardholder's issuing bank on each card transaction, set by the networks. Averages roughly 2% on U.S. credit cards (higher on premium rewards cards) and far less on regulated debit. It funds issuers' rewards programs.`,
    why: `Interchange economics explain rewards-card competition and why Capital One wanted its own network via Discover.` },
  { id: 'mdr', term: 'MDR', full: 'Merchant discount rate', cat: 'pay',
    def: `The all-in percentage a merchant pays to accept cards: interchange (to the issuer) + network/scheme fees (to Visa or Mastercard) + the acquirer's markup. Interchange is the largest component.` },
  { id: 'four-party', term: 'Four-party vs three-party networks', cat: 'pay',
    def: `In the four-party (open-loop) model — Visa, Mastercard — the network connects separate issuers and acquirers and takes no credit risk. In the three-party (closed-loop) model — American Express, Discover — one company is both issuer and network (and often acquirer), capturing more of the economics.` },
  { id: 'issuer-acquirer', term: 'Issuer / acquirer / processor', cat: 'pay',
    def: `The issuer is the cardholder's bank, which extends credit and earns interchange, interest, and fees. The acquirer (merchant acquirer) lets merchants accept cards and settles funds to them. Processors run the technology — authorization, clearing, settlement — for issuers or merchants, often on behalf of banks.` },
  { id: 'payfac', term: 'PayFac', full: 'Payment facilitator', cat: 'pay',
    def: `A provider that boards small merchants as sub-merchants under its own master merchant account (e.g., Stripe, Square, PayPal), making card acceptance easy to embed in software platforms. Acquirers increasingly reach merchants through vertical software (ISV) partners.` },
  { id: 'embedded-finance', term: 'Embedded finance / BaaS', full: 'Banking-as-a-service', cat: 'pay',
    def: `Financial products — payments, accounts, cards, lending — offered inside non-financial platforms through APIs. In banking-as-a-service, a sponsor bank holds the charter and deposits behind a fintech's brand; scrutiny of sponsor banks rose sharply after 2023–24 enforcement actions and the 2024 collapse of middleware provider Synapse.` },
  { id: 'neobank', term: 'Neobank', cat: 'pay',
    def: `A digital-first consumer bank brand. Some rely on partner banks (e.g., Chime); others obtained charters to fund with deposits — SoFi acquired Golden Pacific Bancorp in 2022 and LendingClub acquired Radius Bank in 2021. Valued on growth and unit economics, shifting toward bank metrics once chartered.` },
  { id: 'bnpl', term: 'BNPL', full: 'Buy now, pay later', cat: 'pay',
    def: `Point-of-sale installment loans — often four interest-free payments — where providers such as Affirm, Klarna, and Afterpay earn merchant fees typically above card MDRs, plus interest on longer-term loans. Funded via warehouse lines, ABS, and forward-flow sales; credit performance and regulation are key risks.` },
  { id: 'stablecoin', term: 'Stablecoin', cat: 'pay',
    def: `A crypto token designed to hold a stable value, usually $1, backed by reserves such as cash and T-bills (e.g., USDT, USDC). The U.S. GENIUS Act (July 2025) requires 1:1 high-quality reserves and licensed issuers, and bars issuers from paying interest to holders.`,
    why: `Potential deposit disintermediation, payments disruption, and Treasury-bill demand make stablecoins a live FIG debate.` },
  { id: 'tokenization', term: 'Tokenization', cat: 'pay',
    def: `Representing assets — deposits, money market fund shares, Treasuries, private fund interests — as tokens on a blockchain for faster settlement, programmability, and fractional ownership. Banks are piloting tokenized deposits, and asset managers have launched tokenized money market funds.` },
  { id: 'instant-payments', term: 'RTP / FedNow', full: 'Instant payment rails', cat: 'pay',
    def: `Real-time account-to-account payment networks in the U.S.: The Clearing House's RTP network (2017, bank-owned) and the Federal Reserve's FedNow (launched July 2023). They settle in seconds, 24/7 — an alternative to ACH and, in some uses, cards.` },
  { id: 'chargeback', term: 'Chargeback', cat: 'pay',
    def: `A reversal of a card transaction after the cardholder disputes it through the issuer (fraud, goods not received). The merchant bears the cost unless it successfully contests; elevated chargebacks are a key risk for acquirers and payfacs.` },
  { id: 'risk-adjusted-margin', term: 'Risk-adjusted margin (cards)', cat: 'pay',
    def: `Card revenue (net interest income plus fees and interchange, net of rewards) minus net charge-offs, divided by average loans. The best single gauge of a card portfolio's profitability before operating expenses.` },
  { id: 'cross-border', term: 'Cross-border volume', cat: 'pay',
    def: `Card spending where the issuer and merchant are in different countries — the networks' highest-margin revenue, driven by travel and e-commerce and sensitive to FX volatility.` },
  { id: 'securitization', term: 'Securitization / ABS', cat: 'pay',
    def: `Pooling loans (mortgages, auto, cards, student loans) in a trust that issues asset-backed securities in tranches with credit enhancement — subordination, overcollateralization, excess spread. Provides funding and potential capital relief; U.S. rules generally require sponsors to retain 5% of the credit risk.` },
  { id: 'rule-of-40', term: 'Rule of 40', cat: 'pay',
    def: `Revenue growth % + profit margin % (EBITDA or free cash flow) ≥ 40 — a quick test of balance between growth and profitability for fintech and software companies. Those above 40 tend to earn premium multiples.` },

  // ───────────────────────── Rates & Markets ─────────────────────────
  { id: 'fed-funds', term: 'Fed funds rate', cat: 'mkt',
    def: `The overnight rate at which banks lend reserves to each other. The FOMC sets a target range and steers the effective rate using interest on reserve balances (IORB) and the overnight reverse repo rate. Anchors prime, SOFR-based loan pricing, and deposit costs.` },
  { id: 'sofr', term: 'SOFR', full: 'Secured Overnight Financing Rate', cat: 'mkt',
    def: `A broad measure of the cost of overnight borrowing collateralized by Treasuries in the repo market, published daily by the New York Fed. It replaced USD LIBOR, whose panel-based publication ended in June 2023; term SOFR is used for most new floating-rate loans.` },
  { id: 'yield-curve', term: 'Yield curve / 2s10s', cat: 'mkt',
    def: `Treasury yields plotted across maturities; "2s10s" is the 10-year yield minus the 2-year. Banks borrow short and lend long, so a steeper curve generally supports NIM. The 2s10s curve was inverted from mid-2022 until September 2024.` },
  { id: 'bear-bull', term: 'Bull/bear steepening & flattening', cat: 'mkt',
    def: `Steepening widens the long–short spread; flattening narrows it. "Bull" moves are led by falling yields, "bear" moves by rising yields. A bull steepener — short rates falling faster, as when the Fed cuts — tends to help banks through lower deposit costs and AOCI recovery.` },
  { id: 'duration', term: 'Duration', cat: 'mkt',
    def: `Sensitivity of a bond's price to interest rates: % price change ≈ −modified duration × change in yield, so a bond with 6 years' duration falls ~6% if yields rise 100bp. Banks and insurers manage the duration gap between their assets and liabilities.` },
  { id: 'convexity', term: 'Convexity / negative convexity', cat: 'mkt',
    def: `The curvature of the price–yield relationship. Plain bonds have positive convexity (price gains when yields fall exceed losses when they rise). Mortgages and MBS have negative convexity: prepayments rise as rates fall, capping gains, and duration extends as rates rise.` },
  { id: 'dv01', term: 'DV01', cat: 'mkt',
    def: `Dollar value of a one-basis-point change in yield: modified duration × price × 0.0001 (per unit of face value). Used to size hedges and express rate risk in dollars.` },
  { id: 'credit-spread', term: 'Credit spread', cat: 'mkt',
    def: `The extra yield over Treasuries (or swaps) investors demand for default and liquidity risk. Spreads widen in stress and tighten when risk appetite is strong, moving bank funding costs, loan pricing, and insurers' new-money yields.` },
  { id: 'swaps', term: 'Interest rate swaps', full: 'Receive-fixed / pay-fixed', cat: 'mkt',
    def: `Contracts exchanging fixed for floating payments on a notional amount. Banks receive fixed to lock in asset yields and reduce asset sensitivity, and pay fixed to hedge fixed-rate securities or loans against rising rates; designated as fair-value or cash-flow hedges under hedge accounting.` },
  { id: 'qe-qt', term: 'QE / QT', full: 'Quantitative easing / tightening', cat: 'mkt',
    def: `Quantitative easing is central bank asset purchases that add reserves — and deposits — to the banking system; quantitative tightening lets holdings run off, draining them. In October 2025 the Fed announced it would end balance-sheet runoff on December 1, 2025 (verify current).` },
  { id: 'on-rrp', term: 'ON RRP', full: 'Overnight reverse repo facility', cat: 'mkt',
    def: `A Fed facility where money market funds and other eligible counterparties invest cash overnight at a set rate, putting a floor under short-term rates. Balances peaked above $2T in 2022–23 and fell to low levels by 2025 as QT and heavy T-bill issuance drew the cash away.` },
  { id: 'bank-reserves', term: 'Bank reserves / IORB', cat: 'mkt',
    def: `Balances banks hold at the Federal Reserve, earning interest on reserve balances (IORB). They count as Level 1 HQLA; reserve requirements have been 0% since March 2020. Scarce reserves can trigger money-market stress, as in the September 2019 repo spike.` },
  { id: 'agency-mbs', term: 'Agency vs non-agency MBS', cat: 'mkt',
    def: `Agency MBS are guaranteed by Ginnie Mae (explicit U.S. government backing, 0% risk weight) or Fannie Mae and Freddie Mac (GSEs, 20% risk weight), so investors bear prepayment and rate risk but little credit risk. Non-agency MBS carry credit risk. Agency MBS are a staple of bank securities portfolios.` },
  { id: 'bkx-kre', term: 'BKX / KRE', cat: 'mkt',
    def: `Bank stock benchmarks: the KBW Nasdaq Bank Index (BKX) tracks 24 large U.S. banks; the SPDR S&P Regional Banking ETF (KRE) holds an equal-weighted basket of regional banks. Know their recent performance before any FIG interview.` },
  { id: 'exchanges', term: 'Exchanges & market data', cat: 'mkt',
    def: `Exchange groups (CME, ICE, Nasdaq, Cboe) earn trading and clearing fees, which rise with volumes and volatility, plus recurring market data, index licensing, listings, and technology revenue. The recurring data and index streams earn premium multiples.` },

  // ───────────────────── Accounting & Valuation ─────────────────────
  { id: 'ev', term: 'Enterprise value', full: 'EV', cat: 'acct',
    def: `The value of a company's core operations to all capital providers: equity value + debt + preferred stock + noncontrolling interest − cash and non-operating assets. Capital-structure neutral; paired with pre-interest metrics such as revenue and EBITDA.`,
    why: `Not meaningful for banks, where deposits and debt are operating liabilities — use equity value with P/E and P/TBV instead.` },
  { id: 'equity-value', term: 'Equity value', cat: 'acct',
    def: `The value attributable to common shareholders: diluted shares outstanding × share price. Paired with post-interest metrics — net income, EPS, book value — and the basis for every bank and insurance multiple.` },
  { id: 'tsm', term: 'TSM', full: 'Treasury stock method', cat: 'acct',
    def: `Computes dilution from in-the-money options and warrants by assuming exercise proceeds buy back stock at the current price: net new shares = options − (options × strike ÷ share price). RSUs are added in full; convertible securities use the if-converted method.` },
  { id: 'ebitda', term: 'EBITDA', cat: 'acct',
    def: `Earnings before interest, taxes, depreciation, and amortization — a capital-structure-neutral proxy for operating cash flow that ignores capex, working capital, and taxes. Meaningless for banks and insurers, where interest and investment income are core operations; still standard for brokers, payments, and asset managers.` },
  { id: 'ufcf-lfcf', term: 'UFCF vs LFCF', full: 'Unlevered vs levered free cash flow', cat: 'acct',
    def: `Unlevered FCF = EBIT × (1 − t) + D&A − capex − Δ NWC: cash available to all capital providers, discounted at WACC to get enterprise value. Levered FCF also deducts after-tax interest and debt repayment: cash available to equity, discounted at the cost of equity.` },
  { id: 'wacc', term: 'WACC', full: 'Weighted average cost of capital', cat: 'acct',
    def: `E/(D+E) × cost of equity + D/(D+E) × cost of debt × (1 − t), using market-value or target weights. The discount rate for unlevered cash flows. Not used to value banks — a bank DDM discounts at the cost of equity.` },
  { id: 'capm', term: 'CAPM / cost of equity', cat: 'acct',
    def: `Cost of equity = risk-free rate + beta × equity risk premium, typically the 10-year Treasury yield, an ERP of ~4.5–6%, and a levered beta. Unlevered beta = levered beta ÷ [1 + (1 − t) × D/E]. For banks, use the observed levered beta (leverage is the business); U.S. bank costs of equity are often ~10–12%.` },
  { id: 'terminal-value', term: 'Terminal value', cat: 'acct',
    def: `Value of cash flows beyond the projection period, via Gordon growth — FCF × (1 + g) ÷ (r − g) — or an exit multiple. Often 60–80% of total DCF value, so cross-check the implied exit multiple against the implied perpetual growth rate.` },
  { id: 'mid-year', term: 'Mid-year convention', cat: 'acct',
    def: `Assumes cash flows arrive mid-period on average, so year t is discounted t − 0.5 periods, slightly increasing value. A Gordon-growth terminal value is discounted on the same mid-year basis, while an exit-multiple terminal value is discounted a full N years.` },
  { id: 'ddm', term: 'DDM', full: 'Dividend discount model', cat: 'acct',
    def: `Values equity as the present value of future dividends — for banks, capital distributable above a target CET1 ratio — plus a terminal value, discounted at the cost of equity. Steps: project earnings and RWA, hold a target capital ratio, distribute the excess, and apply a terminal P/E or P/TBV.`,
    why: `The bank equivalent of a DCF — expect "walk me through a bank DDM."` },
  { id: 'pbv-ptbv', term: 'P/BV and P/TBV', cat: 'acct',
    def: `Price ÷ book value per share and price ÷ tangible book value per share — the core multiples for balance-sheet businesses: P/TBV for banks (excluding goodwill, as regulators do) and P/BV (often ex-AOCI) for insurers. Justified P/TBV = (ROTCE − g) ÷ (cost of equity − g).` },
  { id: 'pe', term: 'P/E', full: 'Price-to-earnings', cat: 'acct',
    def: `Share price ÷ earnings per share, usually on forward consensus EPS. Used across banks, insurers, asset managers, and payments. For a bank, P/E = P/TBV ÷ ROTCE on a consistent basis — e.g., 1.8x TBV at a 15% ROTCE ≈ 12x earnings.` },
  { id: 'roe', term: 'ROE', full: 'Return on equity', cat: 'acct',
    def: `Net income to common ÷ average common equity. DuPont: ROE = net margin × asset turnover × equity multiplier; for banks, ROE ≈ ROA × (assets ÷ equity). Value is created only when ROE exceeds the cost of equity.` },
  { id: 'comps', term: 'Trading comps', cat: 'acct',
    def: `Valuing a company using multiples (P/E, P/TBV, EV/EBITDA) of similar public companies — same sub-sector, size, business mix, geography, growth, and profitability. Reflects minority-stake trading values with no control premium. For banks, regress P/TBV against ROTCE across the peer group.` },
  { id: 'precedents', term: 'Precedent transactions', cat: 'acct',
    def: `Valuation based on multiples paid in comparable M&A deals. Includes control premiums and often synergies, so it usually exceeds trading comps. Bank precedents focus on P/TBV, P/E, core deposit premium, and market premium.` },
  { id: 'dta-dtl', term: 'DTA / DTL', full: 'Deferred tax asset / liability', cat: 'acct',
    def: `A DTL arises when book taxes exceed cash taxes today (e.g., accelerated tax depreciation, asset write-ups in a stock deal); a DTA when cash taxes come first (e.g., NOLs, loan-loss reserves not yet deductible). Banks must deduct certain DTAs, such as those from NOL carryforwards, from CET1.` },
  { id: 'goodwill', term: 'Goodwill & intangibles', cat: 'acct',
    def: `Goodwill is the excess of purchase price over the fair value of identifiable net assets acquired; public companies don't amortize it but test it for impairment. Identifiable intangibles (core deposit intangibles, customer relationships) are amortized. Both are deducted from regulatory capital and excluded from TBV.` },
  { id: 'nwc', term: 'Net working capital', full: 'NWC', cat: 'acct',
    def: `Operating current assets (receivables, inventory, prepaids) minus operating current liabilities (payables, accruals, deferred revenue), excluding cash and debt. An increase consumes cash. Not a meaningful concept for banks, whose balance sheet is the business.` },
  { id: 'fv-hierarchy', term: 'Fair value hierarchy (Level 1/2/3)', cat: 'acct',
    def: `ASC 820 ranks fair value inputs: Level 1 = quoted prices in active markets; Level 2 = observable inputs such as comparable prices and yield curves; Level 3 = unobservable, model-based inputs. Large Level 3 balances — e.g., private credit and illiquid loans — draw extra scrutiny.` },
  { id: 'equity-method', term: 'Equity method', cat: 'acct',
    def: `Accounting for investments with significant influence (generally 20–50% ownership): carried as a single balance-sheet line, with the investor recording its share of the investee's net income. Above 50%, consolidate and show noncontrolling interest; below 20%, carry at fair value.` },

  // ─────────────────────────── M&A & LBO ───────────────────────────
  { id: 'accretion-dilution', term: 'Accretion / dilution', cat: 'ma',
    def: `Whether a deal raises (accretive) or lowers (dilutive) the acquirer's pro forma EPS versus standalone. Quick test: accretive if the target's earnings yield on the purchase price exceeds the acquirer's weighted after-tax cost of funding — foregone interest on cash, after-tax cost of new debt, and the earnings yield (1 ÷ P/E) on stock issued.` },
  { id: 'synergies', term: 'Synergies / cost saves', cat: 'ma',
    def: `Cost reductions or revenue gains from combining businesses. In-market bank deals typically target cost saves of roughly 25–40% of the target's non-interest expense, phased in over one to two years, with one-time merger charges on top; investors give little credit for revenue synergies.` },
  { id: 'ppa', term: 'PPA', full: 'Purchase price allocation', cat: 'ma',
    def: `Allocating the purchase price to the target's assets and liabilities at fair value: writing assets up or down, recognizing new identifiable intangibles, recording deferred taxes, and booking the residual as goodwill. In bank deals, the key items are loan, securities, deposit, and debt marks plus the core deposit intangible.` },
  { id: 'cdi', term: 'CDI', full: 'Core deposit intangible', cat: 'ma',
    def: `An identifiable intangible recorded in bank acquisitions for the value of the target's stable, low-cost core deposits — funding cheaper than market alternatives. Often ~1–4% of core deposits (higher when rates are higher) and amortized over roughly 7–10 years, usually on an accelerated basis.`,
    why: `CDI amortization depresses GAAP EPS, which is why bank acquirers highlight cash (tangible) EPS.` },
  { id: 'credit-mark', term: 'Credit mark', cat: 'ma',
    def: `The fair value discount on an acquired loan portfolio reflecting expected lifetime credit losses, set at closing under purchase accounting. A major diligence item: a bigger mark reduces TBV at close but de-risks future earnings.` },
  { id: 'rate-mark', term: 'Interest rate mark', cat: 'ma',
    def: `The fair value discount on acquired fixed-rate loans and securities yielding below current market rates (a premium if above). The discount accretes into interest income over the assets' remaining lives — "purchase accounting accretion" — lifting NIM and EPS and gradually rebuilding capital.`,
    why: `Large rate marks in 2023–24 made bank deals look EPS-accretive but heavily TBV-dilutive at close.` },
  { id: 'pcd', term: 'PCD loans', full: 'Purchased credit-deteriorated', cat: 'ma',
    def: `Acquired loans with more-than-insignificant credit deterioration since origination. Under CECL their allowance is added to the loan's amortized cost basis at acquisition (the "gross-up"), with no income-statement hit — unlike non-PCD loans, which require a day-2 provision.` },
  { id: 'cecl-double-count', term: 'CECL double count', cat: 'ma',
    def: `For acquired non-PCD loans, the buyer records a fair value credit mark and must also book a day-2 CECL allowance through provision expense — counting expected losses twice and reducing TBV and capital at close. The FASB acted in 2025 to extend the gross-up treatment to most acquired "seasoned" loans (verify the effective date).` },
  { id: 'tbv-dilution', term: 'TBV dilution', cat: 'ma',
    def: `The decline in the acquirer's tangible book value per share from a deal, driven by goodwill and intangibles created (any premium over the target's TBV), purchase accounting marks, and merger charges. In an all-stock deal, TBVPS is diluted when the deal's P/TBV exceeds the acquirer's own P/TBV.` },
  { id: 'tbv-earnback', term: 'TBV earnback', cat: 'ma',
    def: `How long it takes to rebuild a deal's TBVPS dilution through incremental earnings. Simple method: dilution ÷ annual EPS accretion; crossover method: years until pro forma TBVPS overtakes the standalone projection. Investors generally look for about 3 years or less.` },
  { id: 'core-deposit-premium', term: 'Core deposit premium', cat: 'ma',
    def: `(Deal value − target TBV) ÷ core deposits (excluding large CDs and brokered deposits): the premium paid per dollar of core deposits. A standard bank M&A pricing metric alongside P/TBV, P/E, and market premium.` },
  { id: 'moe', term: 'MOE', full: 'Merger of equals', cat: 'ma',
    def: `A combination of similar-size companies with little or no premium and shared governance — board seats, CEO and chair roles, headquarters, name. Classic bank example: BB&T–SunTrust (Truist, 2019); Pinnacle–Synovus (2025) was another near-equal-ownership combination.` },
  { id: 'exchange-ratio', term: 'Fixed exchange ratio / collar', cat: 'ma',
    def: `A fixed exchange ratio sets the number of acquirer shares per target share, so deal value floats with the acquirer's stock until closing — the norm in bank M&A. A fixed-price structure floats the ratio instead. A collar limits these swings within a price band, often with walk-away rights outside it.` },
  { id: 'control-premium', term: 'Control / offer premium', cat: 'ma',
    def: `The amount paid above the target's unaffected share price for control: offer price ÷ unaffected price − 1. Typically ~20–40% for U.S. public targets; bank MOEs often carry little or no premium.` },
  { id: 'bargain-purchase', term: 'Bargain purchase gain', cat: 'ma',
    def: `When the fair value of net assets acquired exceeds the price paid (negative goodwill), the acquirer recognizes a gain in net income after re-checking its valuation — as with JPMorgan–First Republic and UBS–Credit Suisse in 2023.` },
  { id: 'stock-vs-asset', term: 'Stock vs asset deal / 338(h)(10)', cat: 'ma',
    def: `In a stock purchase, the target's tax basis carries over, so write-ups create DTLs and aren't tax-deductible. In an asset purchase, the buyer gets a stepped-up basis with tax-deductible D&A on write-ups and goodwill. A 338(h)(10) election treats certain stock purchases as asset purchases for tax.` },
  { id: 'fairness-opinion', term: 'Fairness opinion', cat: 'ma',
    def: `A financial adviser's opinion to a board that the consideration in a transaction is fair, from a financial point of view, to shareholders — backed by comps, precedents, and DCF/DDM analyses. A standard investment banking deliverable in public M&A.` },
  { id: 'deal-protections', term: 'Deal protections', cat: 'ma',
    def: `Merger-agreement terms protecting a signed deal: no-shop clauses (with fiduciary outs), go-shop periods, matching rights, and target termination fees — often ~2–4% of equity value — plus reverse termination fees for buyer-side risks such as regulatory or financing failure.` },
  { id: 'hhi', term: 'HHI', full: 'Herfindahl-Hirschman Index', cat: 'ma',
    def: `A concentration measure: the sum of squared market shares (0–10,000). In bank merger reviews, regulators and the DOJ examine deposit-based HHIs in each local market; large increases can require branch divestitures.` },
  { id: 'bank-merger-approvals', term: 'Bank merger approvals', cat: 'ma',
    def: `U.S. bank deals need Federal Reserve approval for the holding company (BHC Act) and approval from the bank-level regulator — OCC, FDIC, or Fed — under the Bank Merger Act, plus DOJ competitive review and shareholder votes. Reviews weigh competition, CRA records, financial stability, and management; approvals sped up markedly in 2025 (verify current).` },
  { id: 'cash-eps', term: 'Cash / tangible EPS', cat: 'ma',
    def: `EPS excluding after-tax amortization of acquired intangibles such as the CDI. Bank acquirers present accretion on this basis because the amortization is a non-cash byproduct of acquisition accounting.` },
  { id: 'lbo', term: 'LBO', full: 'Leveraged buyout', cat: 'ma',
    def: `An acquisition funded mainly with debt plus sponsor equity; returns come from EBITDA growth, debt paydown, and multiple expansion. Sources (debt, sponsor and rollover equity, cash) must equal uses (purchase price, refinancing, fees). Banks rarely fit (capital rules, BHC Act control limits), but brokers, wealth managers, and payments companies are common FIG LBOs.` },
  { id: 'irr-moic', term: 'IRR / MOIC', cat: 'ma',
    def: `MOIC = total value returned ÷ equity invested, ignoring time. IRR = the annualized discount rate that sets the NPV of all cash flows to zero. Rules of thumb: 2x in 3 years ≈ 26%, 2x in 5 years ≈ 15%, 2.5x in 5 years ≈ 20%, 3x in 5 years ≈ 25%.` },
  { id: 'earnout', term: 'Earnout', cat: 'ma',
    def: `Contingent consideration paid to sellers if the business hits future targets (revenue, EBITDA). Common in insurance brokerage and wealth/RIA acquisitions to bridge valuation gaps and retain key producers.` },
];
